def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for block in iter(lambda:f.read(8388608),b''):h.update(block)
 return h.hexdigest()
def main():
 R=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);AR=Path(os.environ['PANCANCER_ANNOTATION_ROOT']);P=R/'immune_same_name_family_source_review_v1';L=P/'CM_edge_LR_extraction_v2';U=AR/'20261010_uniform_expression_annotation_v1';B=AR/'20261010_expression_annotation_downstream_v1';O=P/'CM_native_expression_preflight_v1';planpath=Path(os.environ['PANCANCER_NATIVE_PREFLIGHT_PLAN']);plan=json.loads(planpath.read_text());assert sha(__file__)==plan['producer_sha256'] and not O.exists()
 for n,h in plan['native_cache']['root_files'].items():assert sha(U/n)==h
 assert json.loads((U/'independent_audit.json').read_text())['status']=='PASS_FULL_SCOPE_EXPRESSION_READBACK_AND_INDEPENDENT_PILOT';assert sha(L/'inventory.json')==plan['extraction_inventory_sha256'];li=json.loads((L/'inventory.json').read_text());catalog=pd.read_csv(U/'all_node_number_catalog.tsv',sep='\t',keep_default_na=False);current=pd.read_csv(B/'downstream_review_v2/number_to_annotation_dictionary.tsv',sep='\t',keep_default_na=False);assert sha(B/'downstream_review_v2/number_to_annotation_dictionary.tsv')==plan['current_catalogue_sha256'];lookup=current.set_index('node_id').subCluster.to_dict();counts=pd.read_csv(B/'inputs/sample_major_subcluster_counts.tsv',sep='\t');assert sha(B/'inputs/sample_major_subcluster_counts.tsv')==plan['current_counts_sha256'];groups=pd.read_csv(L/'all68_directed_group_summary.tsv',sep='\t');assert sha(L/'all68_directed_group_summary.tsv')==li['outputs']['all68_directed_group_summary.tsv'];O.mkdir();(O/'private_group_features').mkdir();summaries=[];total_observed=0;start=datetime.now(timezone.utc).isoformat()
 for sid,gg in groups.groupby('gse_id',sort=True):
  p=U/'by_gse'/sid;expect=plan['native_cache']['sources'][sid];assert sha(p/'manifest.json')==expect['manifest_sha256'];m=json.loads((p/'manifest.json').read_text());assert m['status']=='COMPLETE_EXACT_MEMBER_EXPRESSION_EVIDENCE'
  for n,h in m['output_sha256'].items():assert sha(p/n)==h
  units=pd.read_csv(p/'units.tsv',sep='\t',keep_default_na=False);genes=pd.read_csv(p/'genes.tsv',sep='\t',keep_default_na=False).gene.to_numpy(dtype=str);assert pd.Index(genes).is_unique;selected=units[units.candidate_eligible].copy();selected['subCluster']=catalog.node_id.to_numpy()[selected.node_index];selected['subCluster']=selected.subCluster.map(lookup);assert selected.subCluster.notna().all();index=selected.set_index(['sample_uid','subCluster']);assert index.index.is_unique;expected=counts[counts.sampleID.isin(selected.sample_uid)].set_index(['sampleID','subCluster']);assert set(index.index)==set(expected.index);assert np.array_equal(index.n_cells.to_numpy(),expected.loc[index.index].n_cells.to_numpy())
  positive=load_npz(p/'positive_counts.npz').tocsr();logs=load_npz(p/'sum_log1p_CP10K.npz').tocsr();cp=load_npz(p/'sum_CP10K.npz').tocsr();assert positive.shape==logs.shape==cp.shape==(len(units),len(genes));assert (positive.data>=0).all() and (positive.data==np.floor(positive.data)).all() and np.isfinite(logs.data).all() and (logs.data>=0).all();cp_total=np.asarray(cp.sum(axis=1)).ravel();assert np.allclose(cp_total,units.n_cells.to_numpy()*10000,rtol=2e-6,atol=.02);n_detected_sum=np.asarray(positive.sum(axis=1)).ravel();log_complexity_sum=np.asarray(logs.sum(axis=1)).ravel();observed_count=0;bad_product=0;bad_means=0;max_abs_product=0.;max_abs_means=0.;matched_units=set();geneidx={g:i for i,g in enumerate(genes)}
  for group in gg.itertuples():
   f=L/'private_group_arrays'/(group.group_id+'.npz');assert sha(f)==li['outputs'][str(f.relative_to(L))];b=dict(np.load(f,allow_pickle=False));samples=b['samples'];src=index.loc[[(s,group.source) for s in samples]];dst=index.loc[[(s,group.target) for s in samples]];assert np.array_equal(src.n_cells,b['source_n']) and np.array_equal(dst.n_cells,b['target_n']);sr=src.unit_row.to_numpy(int);tr=dst.unit_row.to_numpy(int);matched_units.update(sr);matched_units.update(tr);components=sorted({s for lr in zip(b['ligands'],b['receptors']) for component in lr for s in component.split('_') if s in geneidx});idx=[geneidx[g] for g in components];pos={g:i for i,g in enumerate(components)};S=logs[sr][:,idx].toarray()/src.n_cells.to_numpy()[:,None];T=logs[tr][:,idx].toarray()/dst.n_cells.to_numpy()[:,None];out=np.full((len(samples),len(b['ligands']),2),np.nan)
